@php $editing=isset($role); $selected=old('permissions',$editing?$role->permissions->pluck('id')->all():[]); @endphp<form class="portal-form" method="post" action="{{ $editing?route('admin.roles.update',$role):route('admin.roles.store') }}">@csrf @if($editing)@method('put')@endif<div class="form-grid"><div class="portal-field"><label for="name">Role name</label><input class="portal-input" id="name" name="name" value="{{ old('name',$role->name??'') }}" required><x-portal.field-error name="name" /></div><div class="portal-field"><label for="slug">Slug <span>system slugs cannot change</span></label><input class="portal-input" id="slug" name="slug" value="{{ old('slug',$role->slug??'') }}" @disabled($editing&&$role->is_system)></div><div class="portal-field field-span"><label for="description">Description</label><textarea class="portal-textarea" id="description" name="description" rows="3">{{ old('description',$role->description??'') }}</textarea></div></div><fieldset class="portal-field"><legend>Permissions</legend><div class="form-grid">@foreach($permissions as $group=>$items)<section class="portal-card"><div class="portal-card-head"><h3>{{ str($group)->headline() }}</h3></div><div class="portal-card-body">@foreach($items as $permission)<label class="check-row" style="margin:.55rem 0"><input type="checkbox" name="permissions[]" value="{{ $permission->id }}" @checked(in_array($permission->id,$selected))><span><strong>{{ $permission->name }}</strong><small style="display:block;color:var(--portal-muted)">{{ $permission->description }}</small></span></label>@endforeach</div></section>@endforeach</div></fieldset><div class="form-actions"><a class="portal-button" href="{{ route('admin.roles.index') }}">Cancel</a><button class="portal-button primary" type="submit">{{ $editing?'Save permissions':'Create role' }}</button></div></form>
